import { useMemo, useState } from 'react';
import {
  JxBadge,
  JxButton,
  JxChip,
  JxDivider,
  JxEmptyState,
  JxPagination,
  JxProgressCircle,
} from '@jinx-ui/react';

type SpendStatus = 'active' | 'at-risk' | 'over' | 'paused';

type Project = {
  id: string;
  name: string;
  quotaUsed: number;
  status: SpendStatus;
};

const STATUS_META: Record<
  SpendStatus,
  { label: string; tone: 'success' | 'warning' | 'danger' | 'default' }
> = {
  active: { label: 'В норме', tone: 'success' },
  'at-risk': { label: 'Близко к лимиту', tone: 'warning' },
  over: { label: 'Превышен', tone: 'danger' },
  paused: { label: 'Приостановлен', tone: 'default' },
};

const STATUS_ORDER: SpendStatus[] = ['active', 'at-risk', 'over', 'paused'];

const PROJECTS: Project[] = [
  { id: 'p-01', name: 'Витрина каталога', quotaUsed: 42, status: 'active' },
  { id: 'p-02', name: 'Платёжный шлюз', quotaUsed: 88, status: 'at-risk' },
  { id: 'p-03', name: 'Аналитика событий и пользовательских сессий', quotaUsed: 117, status: 'over' },
  { id: 'p-04', name: 'Мобильный клиент', quotaUsed: 26, status: 'active' },
  { id: 'p-05', name: 'Поисковый индекс', quotaUsed: 73, status: 'at-risk' },
  { id: 'p-06', name: 'Отчёты для бухгалтерии', quotaUsed: 9, status: 'paused' },
  { id: 'p-07', name: 'CDN и медиа', quotaUsed: 61, status: 'active' },
  { id: 'p-08', name: 'Песочница ML', quotaUsed: 104, status: 'over' },
  { id: 'p-09', name: 'Внутренний портал', quotaUsed: 35, status: 'active' },
  { id: 'p-10', name: 'Рассылки', quotaUsed: 91, status: 'at-risk' },
  { id: 'p-11', name: 'Легаси биллинг', quotaUsed: 4, status: 'paused' },
  { id: 'p-12', name: 'Геосервис', quotaUsed: 54, status: 'active' },
];

const PAGE_SIZE = 5;

export default function ProjectSpendPanel() {
  const [statuses, setStatuses] = useState<SpendStatus[]>(STATUS_ORDER);
  const [page, setPage] = useState(1);

  const filtered = useMemo(
    () => PROJECTS.filter((project) => statuses.includes(project.status)),
    [statuses],
  );

  const pageCount = Math.max(1, Math.ceil(filtered.length / PAGE_SIZE));
  const safePage = Math.min(page, pageCount);
  const visible = filtered.slice((safePage - 1) * PAGE_SIZE, safePage * PAGE_SIZE);

  const toggleStatus = (status: SpendStatus) => {
    setPage(1);
    setStatuses((current) =>
      current.includes(status)
        ? current.filter((item) => item !== status)
        : STATUS_ORDER.filter((item) => item === status || current.includes(item)),
    );
  };

  const resetFilters = () => {
    setStatuses(STATUS_ORDER);
    setPage(1);
  };

  return (
    <section
      style={{
        display: 'flex',
        flexDirection: 'column',
        gap: '16px',
        padding: '20px',
        maxWidth: '680px',
        background: 'var(--jx-surface)',
        border: '1px solid var(--jx-border)',
        borderRadius: 'var(--jx-r-lg)',
        boxShadow: 'var(--jx-shadow-sm)',
        fontFamily: 'var(--jx-font-sans)',
        color: 'var(--jx-text)',
      }}
    >
      <header style={{ display: 'flex', flexDirection: 'column', gap: '4px' }}>
        <h2
          style={{
            margin: 0,
            fontFamily: 'var(--jx-font-display)',
            fontSize: '18px',
            color: 'var(--jx-text)',
          }}
        >
          Расход по проектам
        </h2>
        <p style={{ margin: 0, fontSize: '13px', color: 'var(--jx-text-2)' }}>
          Заполненность месячной квоты. Показано {filtered.length} из {PROJECTS.length} проектов.
        </p>
      </header>

      <div
        role="group"
        aria-label="Фильтры по статусу"
        style={{ display: 'flex', flexWrap: 'wrap', gap: '8px' }}
      >
        {STATUS_ORDER.map((status) => {
          const selected = statuses.includes(status);
          return (
            <JxChip
              key={status}
              role="button"
              tabIndex={0}
              aria-pressed={selected}
              active={selected}
              removable={selected}
              onRemove={() => toggleStatus(status)}
              onClick={() => toggleStatus(status)}
              onKeyDown={(event) => {
                if (event.key === 'Enter' || event.key === ' ') {
                  event.preventDefault();
                  toggleStatus(status);
                }
              }}
            >
              {STATUS_META[status].label}
            </JxChip>
          );
        })}
      </div>

      <JxDivider />

      {visible.length === 0 ? (
        <JxEmptyState
          title="Ни один проект не подходит под фильтры"
          message="Сняты все статусы расхода. Верните фильтры, чтобы снова увидеть проекты."
          action={
            <JxButton variant="primary" onClick={resetFilters}>
              Сбросить фильтры
            </JxButton>
          }
        />
      ) : (
        <>
          <ul
            style={{
              listStyle: 'none',
              margin: 0,
              padding: 0,
              display: 'flex',
              flexDirection: 'column',
              gap: '8px',
            }}
          >
            {visible.map((project) => (
              <li
                key={project.id}
                style={{
                  display: 'flex',
                  alignItems: 'center',
                  gap: '16px',
                  padding: '12px 14px',
                  background: 'var(--jx-surface-2)',
                  border: '1px solid var(--jx-border-2)',
                  borderRadius: 'var(--jx-r)',
                }}
              >
                <JxProgressCircle
                  value={project.quotaUsed}
                  showValue
                  aria-label={`Квота проекта «${project.name}» заполнена на ${project.quotaUsed}%`}
                />
                <span style={{ flex: 1, minWidth: 0, display: 'flex', flexDirection: 'column', gap: '2px' }}>
                  <span
                    style={{
                      fontSize: '14px',
                      color: 'var(--jx-text)',
                      overflow: 'hidden',
                      textOverflow: 'ellipsis',
                      whiteSpace: 'nowrap',
                    }}
                    title={project.name}
                  >
                    {project.name}
                  </span>
                  <span style={{ fontSize: '12px', color: 'var(--jx-text-2)', fontFamily: 'var(--jx-font-mono)' }}>
                    {project.quotaUsed}% квоты
                  </span>
                </span>
                <JxBadge tone={STATUS_META[project.status].tone} dot>
                  {STATUS_META[project.status].label}
                </JxBadge>
              </li>
            ))}
          </ul>

          {pageCount > 1 && (
            <JxPagination total={pageCount} page={safePage} onPageChange={setPage} />
          )}
        </>
      )}
    </section>
  );
}

